<script setup>defineProps({fees:{type:Array,default:()=>[]},compact:Boolean});const money=(fee)=>`${fee.currency||'PKR'} ${Number(fee.amount).toLocaleString()}`;</script>
<template><div v-if="fees.length" class="fee-breakdown" :class="{compact}"><div class="fee-heading"><span><i class="bi bi-cash-stack"></i> Fee Structure</span><small>{{fees.length}} {{fees.length===1?'item':'items'}}</small></div><div class="fee-rows"><div v-for="fee in fees" :key="fee.id||fee.type"><span>{{fee.type}} <small>{{fee.basis}}</small></span><b>{{money(fee)}}</b></div></div><p v-if="!compact&&fees.some(f=>f.notes)">{{fees.find(f=>f.notes)?.notes}}</p></div></template>
